from dataclasses import dataclass, asdict, fields

CHANNELS = {'amazon', 'flipkart', 'myntra'}


def _is_number(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool)


@dataclass(frozen=True)
class OrderRecord:
    order_id: str
    sku: str
    qty: int
    price: float
    channel: str

    def __post_init__(self):
        for name in ('order_id', 'sku'):
            value = getattr(self, name)
            if not isinstance(value, str) or not value.strip():
                raise ValueError(f'{name}: must be a non-empty string')
            object.__setattr__(self, name, value.strip())
        if not (isinstance(self.qty, int) and not isinstance(self.qty, bool) and self.qty >= 1):
            raise ValueError('qty: must be an int >= 1')
        if not (_is_number(self.price) and self.price >= 0):
            raise ValueError('price: must be a number >= 0')
        object.__setattr__(self, 'price', float(self.price))
        if not isinstance(self.channel, str) or self.channel.lower() not in CHANNELS:
            raise ValueError(f"channel: unknown '{self.channel}'")
        object.__setattr__(self, 'channel', self.channel.lower())


FIELD_NAMES = [f.name for f in fields(OrderRecord)]


def validate_rows(rows):
    valid, errors = [], []
    for i, row in enumerate(rows):
        missing = [n for n in FIELD_NAMES if n not in row]
        if missing:
            errors.append({'index': i, 'error': f'{missing[0]}: missing'})
            continue
        try:
            rec = OrderRecord(**{n: row[n] for n in FIELD_NAMES})
        except ValueError as e:
            errors.append({'index': i, 'error': str(e)})
            continue
        valid.append(asdict(rec))
    return {'valid': valid, 'errors': errors}
